static bool s_boot_active;
static uint32_t s_boot_start_ms;
static uint16_t s_boot_line[BOOT_LOGO_WIDTH];

/* 调色板取色：把偏蓝的像素（头发、裙子）往饱和蓝推一档。
 * 原图的头发是很深的藏青，小屏上容易看成黑色，这里提亮蓝色通道、
 * 同时压低一点绿色，让它明确读作"蓝"。暖色像素（皮肤、背景）不动。 */
static uint16_t logo_color(uint8_t idx)
{
    uint16_t c = boot_logo_palette[idx];
    uint16_t r = (uint16_t)((c >> 11) & 0x1FU);
    uint16_t g = (uint16_t)((c >> 5) & 0x3FU);
    uint16_t b = (uint16_t)(c & 0x1FU);

    /* 蓝发增强：提亮蓝、压一点绿，让头发明确读作"蓝"而不是黑 */
    if (b > r) {
        b = (uint16_t)(b + ((31U - b) * 3U) / 5U);
        g = (uint16_t)((g * 3U) / 4U);
        if (b > 31U) {
            b = 31U;
        }
    }

    /* 这块 ST7735 面板实际是 BGR 排布，红蓝在硬件上对调
     * （MADCTL 的 RGB 位与实际屏不符）。图片这条路径在这里换回来，
     * 否则会出现"头发发红、背景发蓝"。
     * UI 的配色一直是在当前效果下定稿的，所以只在这一处换，不动全局。 */
    return (uint16_t)((b << 11) | (g << 5) | r);
}

void boot_logo_draw(void)
{
    tft_set_y_offset(0);
    for (uint16_t y = 0; y < BOOT_LOGO_HEIGHT; ++y) {
        for (uint16_t x = 0; x < BOOT_LOGO_WIDTH; ++x) {
            uint8_t index = boot_logo_pixels[(uint32_t)y * BOOT_LOGO_WIDTH + x];
            s_boot_line[x] = logo_color(index);
        }
        tft_draw_rgb565_image(0, (int16_t)y, BOOT_LOGO_WIDTH, 1, s_boot_line);
    }
}

void boot_logo_start(void)
{
    boot_logo_draw();

    /* 绘制完成后再开始 5 s 计时，避免把刷屏时间算进去。 */
    s_boot_start_ms = HAL_GetTick();
    s_boot_active = true;
}

bool boot_logo_active(void)
{
    return s_boot_active;
}

bool boot_logo_tick(uint32_t now_ms)
{
    if (!s_boot_active) {
        return false;
    }
    if ((uint32_t)(now_ms - s_boot_start_ms) >= BOOT_LOGO_MS) {
        s_boot_active = false;
        return true;
    }
    return false;
}

/* 供透明文字取底色：返回图片在 (x,y) 处真正的颜色 */
uint16_t boot_logo_pixel_at(void *ctx, int16_t x, int16_t y)
{
    (void)ctx;
    if (x < 0 || y < 0 ||
        x >= (int16_t)BOOT_LOGO_WIDTH || y >= (int16_t)BOOT_LOGO_HEIGHT) {
        return 0x0000U;
    }
    return logo_color(boot_logo_pixels[(uint32_t)y * BOOT_LOGO_WIDTH + (uint32_t)x]);
}
